def calculate_total(transactions):
    from decimal import Decimal

    total = Decimal("0")

    for transaction in transactions:
        amount = Decimal(str(transaction["amount"]))
        if transaction["type"] == "Payment":
            total += amount
        elif transaction["type"] == "Refund":
            total -= amount

    return total
